using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();

        _reportingConfig = new ReportingConfiguration(
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
            ],
            chatClient,
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "eval-results"));
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task AnswersGreetingCoherently()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(nameof(AnswersGreetingCoherently));
        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you today?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassed();
    }

    [TestMethod]
    public async Task AnswersFactualQuestionRelevantly()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(nameof(AnswersFactualQuestionRelevantly));
        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassed();
    }

    [TestMethod]
    public async Task HandlesFollowUpQuestions()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(nameof(HandlesFollowUpQuestions));
        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about photosynthesis."),
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        messages.Add(new ChatMessage(ChatRole.User, "Can you explain the light-dependent reactions in more detail?"));

        response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassed();
    }
}

